INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('231b91a0-d536-4222-9175-50691c6c6ec9', 'EX01', 'Goblet squat', 'squat', 'legs', 'dumbbell', 1, 1, 3, 8, 12, 'reps', 90, 'Pegang dumbbell di depan dada, kaki selebar bahu, dada tegak. Turun terkontrol hingga paha sejajar lantai lalu dorong melalui tumit. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('73761f48-a059-4079-8795-1c05fe56e222', 'EX02', 'Leg press', 'squat', 'legs', 'gym', 1, 2, 3, 8, 12, 'reps', 90, 'Duduk dengan punggung menempel penuh pada sandaran dan kaki selebar bahu di papan. Turunkan beban hingga lutut membentuk sekitar 90 derajat tanpa mengangkat pinggul, lalu dorong kembali tanpa mengunci lutut. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('509c4e39-de62-42bc-91dc-a8447b36a40b', 'EX03', 'Bodyweight squat', 'squat', 'legs', 'bodyweight', 1, 3, 3, 10, 15, 'reps', 60, 'Berdiri kaki selebar bahu, kencangkan perut, dan jaga punggung netral. Turunkan pinggul seperti hendak duduk lalu berdiri kembali dengan stabil. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('9d95d6af-7fca-46e5-aa33-9b52705976b2', 'EX04', 'Barbell back squat', 'squat', 'legs', 'gym', 2, 4, 3, 6, 10, 'reps', 120, 'Letakkan bar di punggung atas, kencangkan inti tubuh, dan tarik napas sebelum turun. Turun terkontrol dengan lutut searah ujung kaki lalu dorong naik secara seimbang. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('74cb5a85-19a6-4bdd-8e9b-a6ba71f07b15', 'EX05', 'Dumbbell Romanian deadlift', 'hinge', 'hamstrings', 'dumbbell', 1, 1, 3, 8, 12, 'reps', 90, 'Pegang dumbbell di depan paha, lutut sedikit ditekuk, punggung rata. Dorong pinggul ke belakang hingga terasa regangan di paha belakang lalu kembali berdiri dengan mengencangkan glutes. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('7387bbea-f8e8-4b41-9155-1a1a9ce5c97c', 'EX06', 'Barbell Romanian deadlift', 'hinge', 'hamstrings', 'gym', 2, 2, 3, 6, 10, 'reps', 120, 'Pegang bar selebar bahu dekat paha dan jaga tulang belakang netral. Engselkan pinggul ke belakang secara terkontrol lalu dorong pinggul maju untuk kembali berdiri. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('7977e999-cdc9-4347-b3f1-6d64421f60d0', 'EX07', 'Glute bridge', 'hinge', 'glutes', 'bodyweight', 1, 3, 3, 10, 15, 'reps', 60, 'Berbaring telentang dengan lutut ditekuk dan telapak kaki menapak lantai. Angkat pinggul hingga tubuh membentuk garis lurus dari bahu ke lutut, tahan sejenak, lalu turunkan perlahan. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('2f6f0282-aa12-4bc8-9099-c6726d978f63', 'EX08', 'Dumbbell split squat', 'lunge', 'legs', 'dumbbell', 1, 1, 3, 8, 12, 'reps', 90, 'Berdiri posisi langkah memanjang sambil memegang dumbbell di samping tubuh. Turunkan lutut belakang mendekati lantai dengan batang tubuh tegak lalu dorong naik melalui kaki depan. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('95b0f7d6-a6a5-441e-9399-7b00549a27da', 'EX09', 'Reverse lunge', 'lunge', 'legs', 'bodyweight', 1, 2, 3, 8, 12, 'reps', 60, 'Langkahkan satu kaki ke belakang dan turunkan tubuh hingga kedua lutut sekitar 90 derajat. Dorong melalui kaki depan untuk kembali ke posisi berdiri dengan seimbang. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('7d2b34e1-2dc3-4cd5-9427-925b9a9dd677', 'EX10', 'Dumbbell bench press', 'horizontal_push', 'chest', 'dumbbell', 1, 1, 3, 8, 12, 'reps', 90, 'Berbaring di bangku datar dengan kaki menapak kuat dan belikat ditarik rapat. Turunkan dumbbell ke samping dada dengan siku sekitar 45 derajat lalu dorong ke atas terkontrol. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('f7c0e5aa-7d5c-49d3-95a3-804b0fe55a4b', 'EX11', 'Machine chest press', 'horizontal_push', 'chest', 'gym', 1, 2, 3, 8, 12, 'reps', 90, 'Atur tinggi kursi sehingga pegangan sejajar tengah dada dan punggung menempel. Dorong pegangan ke depan tanpa mengunci siku lalu kembalikan perlahan. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('51a4a8a2-7bd4-41ac-ab10-f0298ad4129c', 'EX12', 'Incline push-up', 'horizontal_push', 'chest', 'bodyweight', 1, 3, 3, 8, 15, 'reps', 60, 'Letakkan tangan pada permukaan lebih tinggi seperti bangku dengan tubuh lurus dari kepala hingga tumit. Turunkan dada mendekati tumpuan lalu dorong kembali sambil menjaga inti kencang. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('8a69f14f-3d26-4cfb-a369-fb7df1832038', 'EX13', 'Push-up', 'horizontal_push', 'chest', 'bodyweight', 2, 4, 3, 6, 15, 'reps', 60, 'Posisikan tangan sedikit lebih lebar dari bahu dan tubuh lurus seperti papan. Turunkan dada mendekati lantai dengan siku sekitar 45 derajat lalu dorong naik. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('eee6b004-11e8-4f93-9ee4-5345811790e4', 'EX14', 'One-arm dumbbell row', 'horizontal_pull', 'back', 'dumbbell', 1, 1, 3, 8, 12, 'reps', 90, 'Tumpukan satu tangan dan lutut di bangku dengan punggung rata sejajar lantai. Tarik dumbbell ke arah pinggul sambil merapatkan belikat lalu turunkan terkontrol. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('af76eeac-3eb0-432a-bc82-eb4fa09417fb', 'EX15', 'Seated cable row', 'horizontal_pull', 'back', 'gym', 1, 2, 3, 8, 12, 'reps', 90, 'Duduk tegak dengan lutut sedikit ditekuk dan dada terangkat. Tarik pegangan ke arah perut bawah dengan merapatkan belikat tanpa mengayunkan punggung. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('04266e9d-fcfc-4e7e-ad40-63bf325508b4', 'EX16', 'Prone Y-T raise', 'horizontal_pull', 'back', 'bodyweight', 1, 5, 3, 10, 15, 'reps', 60, 'Berbaring telungkup di matras dengan dahi disangga ringan. Angkat lengan membentuk huruf Y lalu T menggunakan otot punggung atas secara perlahan. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('76ff892d-4913-49a9-9bb4-694f60dc25e8', 'EX17', 'Dumbbell shoulder press', 'vertical_push', 'shoulders', 'dumbbell', 1, 1, 3, 8, 12, 'reps', 90, 'Duduk atau berdiri tegak dengan inti kencang dan dumbbell setinggi bahu. Dorong dumbbell ke atas kepala tanpa melengkungkan punggung bawah lalu turunkan perlahan. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('dc0295d0-6fc0-4dfb-8d9a-b0057488d004', 'EX18', 'Machine shoulder press', 'vertical_push', 'shoulders', 'gym', 1, 2, 3, 8, 12, 'reps', 90, 'Duduk dengan punggung menempel pada sandaran dan pegang handel setinggi bahu. Dorong ke atas secara terkontrol lalu turunkan kembali tanpa membanting beban. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('69c78481-9718-48f5-8455-8ab91bf78130', 'EX19', 'Pike push-up', 'vertical_push', 'shoulders', 'bodyweight', 2, 3, 3, 6, 12, 'reps', 60, 'Bentuk posisi huruf V terbalik dengan pinggul tinggi dan tangan menapak kuat. Tekuk siku untuk menurunkan puncak kepala mendekati lantai lalu dorong kembali. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('c9e2bc54-b9b8-46d0-b25e-f9167388e045', 'EX20', 'Lat pulldown', 'vertical_pull', 'back', 'gym', 1, 1, 3, 8, 12, 'reps', 90, 'Duduk tegak, pegang bar sedikit lebih lebar dari bahu, dan condongkan dada sedikit. Tarik bar ke dada atas dengan mengaktifkan punggung lalu kembalikan perlahan. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('d76b6e32-79f7-46e9-bb56-752cc0b92089', 'EX21', 'Assisted pull-up', 'vertical_pull', 'back', 'gym', 2, 2, 3, 5, 10, 'reps', 90, 'Gunakan mesin bantuan pull-up dengan pegangan selebar bahu. Tarik tubuh hingga dagu melewati palang sambil menjaga inti tetap stabil lalu turun terkontrol. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('a3923da8-9fd2-4bf8-a1a4-78d9de649c5b', 'EX22', 'Plank', 'core', 'core', 'bodyweight', 1, 1, 3, 20, 40, 'seconds', 45, 'Bertumpu pada lengan bawah dan ujung kaki dengan tubuh lurus dari kepala hingga tumit. Kencangkan perut dan glutes sambil bernapas teratur tanpa menurunkan pinggul. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('74daad7e-2dcb-4af1-b20d-15aadbbc2f04', 'EX23', 'Dead bug', 'core', 'core', 'bodyweight', 1, 2, 3, 8, 12, 'reps', 45, 'Berbaring telentang dengan punggung bawah menempel lantai, lengan ke atas, dan lutut 90 derajat. Luruskan lengan dan kaki berlawanan secara perlahan lalu kembali bergantian. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('ce2f8ec6-4f8c-40ac-a2e2-9b11cbfe7f28', 'EX24', 'Side plank', 'core', 'core', 'bodyweight', 1, 3, 2, 15, 30, 'seconds', 45, 'Bertumpu pada satu lengan bawah di samping tubuh dengan kaki ditumpuk dan pinggul terangkat. Jaga garis lurus tubuh pada setiap sisi selama waktu yang ditentukan. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
INSERT INTO public."exercises" ("id", "code", "name", "pattern", "muscle_group", "equipment", "difficulty", "rank", "sets", "reps_min", "reps_max", "unit", "rest_s", "instructions", "contraindication_notes", "is_active", "created_at", "updated_at") VALUES ('4386f077-9172-43e6-8411-f26f4a919b3b', 'EX25', 'Farmer''s carry', 'carry', 'full_body', 'dumbbell', 1, 1, 3, 20, 40, 'seconds', 60, 'Pegang sepasang dumbbell di samping tubuh, tarik bahu ke belakang, dan kencangkan inti. Berjalan dengan langkah pendek dan stabil selama durasi set. Pilih beban yang menyisakan 2–3 repetisi. Hentikan latihan bila nyeri tajam, pusing, atau sesak; konsultasikan ke tenaga kesehatan.', 'Hentikan bila nyeri tajam; bukan pengganti saran tenaga kesehatan.', true, '2026-11-19T14:46:18.639524', '2026-11-19T14:46:18.639524') ON CONFLICT DO NOTHING;
